<title>Chat Wrapped 2025</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;700;900&display=swap');
:root{--jonas:#4A90D9;--laura:#1DB954;--bg1:#0d0d0d;--accent:#1DB954;--pink:#FF6B9D;--purple:#B24BF3;--gold:#FFD700}
*{margin:0;padding:0;box-sizing:border-box}
html,body{height:100%;overflow:hidden;font-family:'Montserrat',sans-serif;background:var(--bg1);color:#fff;cursor:pointer;user-select:none}
.slide{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 24px;opacity:0;pointer-events:none;transition:opacity .6s ease,transform .6s ease;transform:translateX(60px);overflow-y:auto}
.slide.active{opacity:1;pointer-events:all;transform:translateX(0)}
.slide.exit{opacity:0;transform:translateX(-60px)}
.slide h1{font-size:clamp(2rem,6vw,4.5rem);font-weight:900;text-transform:uppercase;letter-spacing:-1px;line-height:1.05;text-align:center;margin-bottom:12px}
.slide h2{font-size:clamp(1.1rem,3vw,1.8rem);font-weight:700;text-align:center;margin-bottom:8px;opacity:.85}
.slide .subtitle{font-size:clamp(.9rem,2vw,1.2rem);opacity:.6;text-align:center;margin-bottom:24px}
.big-number{font-size:clamp(3rem,12vw,8rem);font-weight:900;background:linear-gradient(135deg,var(--accent),var(--pink));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;opacity:0;transform:scale(.5);transition:all .8s cubic-bezier(.17,.67,.29,1.3)}
.big-number.visible{opacity:1;transform:scale(1)}
.chart-wrap{width:min(90vw,700px);max-height:50vh;opacity:0;transform:translateY(30px);transition:all .8s ease .3s}
.chart-wrap.visible{opacity:1;transform:translateY(0)}
#progress{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);display:flex;gap:8px;z-index:100}
#progress .dot{width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,.25);transition:background .3s,transform .3s}
#progress .dot.active{background:var(--accent);transform:scale(1.3)}
.tap-hint{position:fixed;bottom:48px;left:50%;transform:translateX(-50%);font-size:.8rem;opacity:.35;animation:pulse 2s infinite;z-index:100}
@keyframes pulse{0%,100%{opacity:.35}50%{opacity:.7}}
.grad-green{background:linear-gradient(135deg,#0d0d0d 0%,#064e3b 100%)}
.grad-blue{background:linear-gradient(135deg,#0d0d0d 0%,#1e3a5f 100%)}
.grad-pink{background:linear-gradient(135deg,#0d0d0d 0%,#5b1a3a 100%)}
.grad-purple{background:linear-gradient(135deg,#0d0d0d 0%,#3b1a5b 100%)}
.grad-gold{background:linear-gradient(135deg,#0d0d0d 0%,#5b4a1a 100%)}
.grad-fire{background:linear-gradient(135deg,#1a0a00 0%,#6b2000 100%)}
.grad-teal{background:linear-gradient(135deg,#0d0d0d 0%,#0d4d4d 100%)}
.grad-mixed{background:linear-gradient(135deg,#1a0a2e 0%,#0d3b3b 100%)}
.stat-row{display:flex;gap:32px;margin-top:16px;flex-wrap:wrap;justify-content:center}
.stat-card{background:rgba(255,255,255,.07);border-radius:16px;padding:24px 32px;text-align:center;min-width:140px;backdrop-filter:blur(10px);opacity:0;transform:translateY(20px);transition:all .6s ease}
.stat-card.visible{opacity:1;transform:translateY(0)}
.stat-card .label{font-size:.85rem;opacity:.6;margin-bottom:6px}
.stat-card .value{font-size:1.8rem;font-weight:900}
.stat-card .value.jonas-color{color:var(--jonas)}
.stat-card .value.laura-color{color:var(--laura)}
.search-box{position:relative;width:min(85vw,420px);margin:12px auto}
.search-box input{width:100%;padding:14px 20px 14px 48px;border:2px solid rgba(255,255,255,.15);border-radius:16px;background:rgba(255,255,255,.07);color:#fff;font-family:'Montserrat',sans-serif;font-size:1.05rem;font-weight:700;outline:none;backdrop-filter:blur(10px);transition:border-color .3s}
.search-box input::placeholder{color:rgba(255,255,255,.35);font-weight:400}
.search-box input:focus{border-color:var(--accent)}
.search-box .search-icon{position:absolute;left:16px;top:50%;transform:translateY(-50%);font-size:1.2rem;opacity:.4}
#searchResults{text-align:center;min-height:60px;margin:12px 0}
#searchResults .big-number{font-size:clamp(2rem,8vw,5rem)}

/* Mobile optimizations */
@media(max-width:600px){
  .slide{padding:24px 16px;padding-bottom:80px}
  .stat-row{gap:12px}
  .stat-card{padding:16px 18px;min-width:110px;border-radius:12px}
  .stat-card .value{font-size:1.4rem}
  .stat-card .label{font-size:.75rem}
  .chart-wrap{width:95vw;max-height:40vh}
  #progress{bottom:12px;gap:5px}
  #progress .dot{width:7px;height:7px}
  .tap-hint{bottom:32px;font-size:.7rem}
  .search-box{width:92vw}
  .search-box input{padding:12px 16px 12px 42px;font-size:.95rem;border-radius:12px}
  .search-box .search-icon{left:14px;font-size:1rem}
  .big-number{font-size:clamp(2.5rem,14vw,6rem)}
  .slide h1{font-size:clamp(1.8rem,8vw,3.5rem)}
  .slide h2{font-size:clamp(1rem,4vw,1.5rem)}
  .slide .subtitle{font-size:clamp(.8rem,2.5vw,1rem)}
}
@media(max-width:360px){
  .slide{padding:16px 10px;padding-bottom:70px}
  .stat-card{padding:12px 14px;min-width:90px}
  .stat-card .value{font-size:1.2rem}
  .chart-wrap{max-height:35vh}
}
/* Navigation arrows */
.nav-arrow{position:fixed;top:50%;transform:translateY(-50%);z-index:200;background:rgba(255,255,255,.12);border:none;color:rgba(255,255,255,.7);font-size:2rem;width:48px;height:48px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(6px);transition:background .2s,color .2s,opacity .3s;opacity:.7;-webkit-tap-highlight-color:transparent;user-select:none}
.nav-arrow:hover,.nav-arrow:active{background:rgba(255,255,255,.25);color:#fff;opacity:1}
.nav-arrow.nav-prev{left:12px}
.nav-arrow.nav-next{right:12px}
@media(max-width:600px){
  .nav-arrow{top:auto;bottom:52px;width:42px;height:42px;font-size:1.6rem}
  .nav-arrow.nav-prev{left:16px}
  .nav-arrow.nav-next{right:16px}
}
/* Safe area (notched phones) */
@supports(padding:env(safe-area-inset-bottom)){
  #progress{bottom:calc(12px + env(safe-area-inset-bottom))}
  .tap-hint{bottom:calc(36px + env(safe-area-inset-bottom))}
  .slide{padding-bottom:calc(80px + env(safe-area-inset-bottom))}
  .nav-arrow{bottom:calc(52px + env(safe-area-inset-bottom))}
}
</style>
</head>
