const JC='#4A90D9', LC='#1DB954', GC='rgba(255,255,255,0.08)', TC='rgba(255,255,255,0.5)';
Chart.defaults.color = TC;
Chart.defaults.borderColor = GC;
function sc(s){ return s==='Jonas' ? JC : LC; }

function animN(el, target, dur){
  dur = dur || 1500;
  var t0 = performance.now();
  function step(now){
    var p = Math.min((now - t0) / dur, 1);
    var e = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(e * target).toLocaleString();
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

/* ── Slide engine ── */
var TS = 14, cur = 0, slides = [], dots = [], builders = {}, built = {};

function init(){
  for(var i=0;i<TS;i++){
    slides.push(document.getElementById('s'+i));
    var d = document.createElement('div');
    d.className = 'dot';
    document.getElementById('progress').appendChild(d);
    dots.push(d);
  }
  show(0);
}

function show(idx){
  for(var i=0;i<TS;i++){
    slides[i].classList.remove('active','exit');
    if(i===idx) slides[i].classList.add('active');
    else if(i<idx) slides[i].classList.add('exit');
    dots[i].classList.toggle('active', i===idx);
  }
  cur = idx;
  if(!built[idx] && builders[idx]){
    built[idx] = true;
    setTimeout(builders[idx], 350);
  }
}

function next(){ if(cur < TS-1) show(cur+1); }
function prev(){ if(cur > 0) show(cur-1); }

/* Navigation: arrow buttons */
document.getElementById('navPrev').addEventListener('click', function(e){ e.stopPropagation(); prev(); });
document.getElementById('navNext').addEventListener('click', function(e){ e.stopPropagation(); next(); });

/* Click-to-navigate only on non-touch (desktop) */
var isTouch = false;
document.addEventListener('touchstart', function(){ isTouch = true; }, {once: true});
document.addEventListener('click', function(e){
  if(isTouch) return;
  if(e.target.closest('.search-box')) return;
  if(e.target.closest('.nav-arrow')) return;
  if(e.clientX > window.innerWidth * 0.3) next(); else prev();
});

/* Keyboard navigation */
document.addEventListener('keydown', function(e){
  if(e.key==='ArrowRight' || e.key===' ') next();
  if(e.key==='ArrowLeft') prev();
});

/* Swipe navigation (touch devices) */
var tx = 0, ty = 0;
document.addEventListener('touchstart', function(e){ tx = e.touches[0].clientX; ty = e.touches[0].clientY; });
document.addEventListener('touchend', function(e){
  var dx = e.changedTouches[0].clientX - tx;
  var dy = e.changedTouches[0].clientY - ty;
  if(Math.abs(dx) < 50 || Math.abs(dy) > Math.abs(dx)) return;
  if(dx < 0) next(); else prev();
});

/* ── Slide builders ── */

// 1: Total messages
builders[1] = function(){
  var data = D.totalPerDay;
  var total = data.reduce(function(s,r){ return s + parseInt(r.Messages); }, 0);
  var el = document.getElementById('totalMsgNum');
  el.classList.add('visible');
  animN(el, total);
  var mx = data.reduce(function(a,b){ return parseInt(b.Messages) > parseInt(a.Messages) ? b : a; });
  document.getElementById('totalMsgSub').textContent =
    'busiest day: ' + mx.Date + ' with ' + parseInt(mx.Messages).toLocaleString() + ' messages';
};

// 2: Pie chart
builders[2] = function(){
  var data = D.jonasVlaura, j=0, l=0;
  data.forEach(function(r){ j += parseInt(r.Jonas); l += parseInt(r.Laura); });
  var t = j + l;
  document.getElementById('splitCards').innerHTML =
    '<div class="stat-card visible"><div class="label">Jonas</div><div class="value jonas-color">' + j.toLocaleString() + '</div><div class="label">' + (j/t*100).toFixed(1) + '%</div></div>' +
    '<div class="stat-card visible"><div class="label">Laura</div><div class="value laura-color">' + l.toLocaleString() + '</div><div class="label">' + (l/t*100).toFixed(1) + '%</div></div>';
  document.querySelector('#s2 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('pieChart'), {
    type: 'doughnut',
    data: { labels: ['Jonas','Laura'], datasets: [{ data: [j,l], backgroundColor: [JC,LC], borderWidth: 0 }] },
    options: { cutout: '60%', plugins: { legend: { labels: { font: { family:'Montserrat', size:14, weight:'bold' }}}}, animation: { animateRotate: true, duration: 1200 }}
  });
};

// 3: Messages per day + 7-day rolling average
builders[3] = function(){
  var data = D.totalPerDay;
  var vals = data.map(function(r){ return parseInt(r.Messages); });
  var avg = vals.reduce(function(a,b){ return a+b; },0) / vals.length;
  document.getElementById('perDayAvgSub').textContent = 'On average ' + avg.toFixed(1) + ' messages per day';
  var roll = vals.map(function(_,i){
    var s = Math.max(0, i-6);
    var w = vals.slice(s, i+1);
    return w.reduce(function(a,b){ return a+b; },0) / w.length;
  });
  document.querySelector('#s3 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('perDayChart'), {
    type: 'bar',
    data: {
      labels: data.map(function(r){ return r.Date; }),
      datasets: [
        { label:'Messages', data: vals, backgroundColor:'rgba(29,185,84,0.35)', borderColor:'#1DB954', borderWidth:1, borderRadius:2, order:2 },
        { label:'7-day avg', type:'line', data: roll, borderColor:'#FFD700', borderWidth:2.5, pointRadius:0, tension:0.3, fill:false, order:1 }
      ]
    },
    options: {
      responsive:true, maintainAspectRatio:true,
      plugins:{ legend:{ labels:{ font:{ family:'Montserrat', weight:'bold' }}}},
      scales:{
        x:{ type:'time', time:{ unit:'month' }, grid:{ display:false }, ticks:{ font:{ size:10 }}},
        y:{ beginAtZero:true, grid:{ color:GC }}
      },
      animation:{ duration:1400 }
    }
  });
};

// 4: Jonas vs Laura per day
builders[4] = function(){
  var data = D.jonasVlaura;
  document.querySelector('#s4 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('vsChart'), {
    type: 'bar',
    data: {
      labels: data.map(function(r){ return r.Date; }),
      datasets: [
        { label:'Jonas', data: data.map(function(r){ return parseInt(r.Jonas); }), backgroundColor: JC+'99', borderColor: JC, borderWidth:1, borderRadius:2 },
        { label:'Laura', data: data.map(function(r){ return parseInt(r.Laura); }), backgroundColor: LC+'99', borderColor: LC, borderWidth:1, borderRadius:2 }
      ]
    },
    options: {
      responsive:true, maintainAspectRatio:true,
      plugins:{ legend:{ labels:{ font:{ family:'Montserrat', weight:'bold' }}}},
      scales:{
        x:{ type:'time', time:{ unit:'month' }, stacked:true, grid:{ display:false }, ticks:{ font:{ size:10 }}},
        y:{ stacked:true, beginAtZero:true, grid:{ color:GC }}
      },
      animation:{ duration:1400 }
    }
  });
};

// 5: Response time
builders[5] = function(){
  var avg = D.averageResponseTime;
  document.getElementById('responseCards').innerHTML = avg.map(function(r){
    return '<div class="stat-card visible"><div class="label">'+r.Sender+'</div><div class="value" style="color:'+sc(r.Sender)+'">'+parseFloat(r.AvgResponseTime_min).toFixed(1)+' min</div></div>';
  }).join('');
  var rt = D.responseTimeHist;
  var labels = []; for(var i=0;i<60;i++) labels.push(i);
  var ds = Object.keys(rt).map(function(s){ return { label:s, data:rt[s], backgroundColor:sc(s)+'88', borderColor:sc(s), borderWidth:1 }; });
  document.querySelector('#s5 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('responseHist'), {
    type:'bar', data:{ labels:labels, datasets:ds },
    options:{ responsive:true, maintainAspectRatio:true,
      plugins:{ legend:{ labels:{ font:{ family:'Montserrat', weight:'bold' }}}},
      scales:{ x:{ title:{ display:true, text:'Minutes' }, grid:{ display:false }}, y:{ beginAtZero:true, grid:{ color:GC }}},
      animation:{ duration:1200 }
    }
  });
};

// 6: Message length
builders[6] = function(){
  var avg = D.averageMessageLength;
  document.getElementById('lengthCards').innerHTML = avg.map(function(r){
    return '<div class="stat-card visible"><div class="label">'+r.Sender+'</div><div class="value" style="color:'+sc(r.Sender)+'">'+parseFloat(r.AvgMessageLength).toFixed(1)+' chars</div></div>';
  }).join('');
  var ml = D.messageLengthHist;
  var labels = []; for(var i=0;i<50;i++) labels.push(i*4);
  var ds = Object.keys(ml).map(function(s){ return { label:s, data:ml[s], backgroundColor:sc(s)+'88', borderColor:sc(s), borderWidth:1 }; });
  document.querySelector('#s6 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('lengthHist'), {
    type:'bar', data:{ labels:labels, datasets:ds },
    options:{ responsive:true, maintainAspectRatio:true,
      plugins:{ legend:{ labels:{ font:{ family:'Montserrat', weight:'bold' }}}},
      scales:{ x:{ title:{ display:true, text:'Characters' }, grid:{ display:false }}, y:{ beginAtZero:true, grid:{ color:GC }}},
      animation:{ duration:1200 }
    }
  });
};

// 7: Time of day
builders[7] = function(){
  var td = D.timeOfDay;
  var labels = []; for(var i=0;i<24;i++) labels.push(String(i).padStart(2,'0')+':00');
  var ds = Object.keys(td).map(function(s){ return { label:s, data:td[s], backgroundColor:sc(s)+'88', borderColor:sc(s), borderWidth:2, tension:0.4, fill:true, pointRadius:0 }; });
  document.querySelector('#s7 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('hourChart'), {
    type:'line', data:{ labels:labels, datasets:ds },
    options:{ responsive:true, maintainAspectRatio:true,
      plugins:{ legend:{ labels:{ font:{ family:'Montserrat', weight:'bold' }}}},
      scales:{ x:{ grid:{ display:false }}, y:{ beginAtZero:true, grid:{ color:GC }}},
      animation:{ duration:1400 }
    }
  });
};

// 8: Weekday
builders[8] = function(){
  var wd = D.weekday;
  var dn = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
