    options:{ responsive:true, maintainAspectRatio:true,
      plugins:{ legend:{ labels:{ font:{ family:'Montserrat', weight:'bold' }}}},
      scales:{ x:{ grid:{ display:false }}, y:{ beginAtZero:true, grid:{ color:GC }}},
      animation:{ duration:1200 }
    }
  });
};

// 9: Hearts
builders[9] = function(){
  var data = D.heartsPerDay;
  var total = data.reduce(function(s,r){ return s + parseInt(r.Hearts); }, 0);
  var el = document.getElementById('heartNum');
  el.classList.add('visible'); animN(el, total);
  document.querySelector('#s9 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('heartChart'), {
    type:'bar',
    data:{ labels: data.map(function(r){ return r.Date; }), datasets:[{ data: data.map(function(r){ return parseInt(r.Hearts); }), backgroundColor:'#FF6B9D99', borderColor:'#FF6B9D', borderWidth:1, borderRadius:2 }]},
    options:{ responsive:true, maintainAspectRatio:true, plugins:{ legend:{ display:false }},
      scales:{ x:{ type:'time', time:{ unit:'month' }, grid:{ display:false }, ticks:{ font:{ size:10 }}}, y:{ beginAtZero:true, grid:{ color:GC }}},
      animation:{ duration:1400 }
    }
  });
};

// 10: Bebi
builders[10] = function(){
  var data = D.bebisPerDay;
  var total = data.reduce(function(s,r){ return s + parseInt(r.Bebis); }, 0);
  var el = document.getElementById('bebiNum');
  el.classList.add('visible'); animN(el, total);
  document.querySelector('#s10 .chart-wrap').classList.add('visible');
  new Chart(document.getElementById('bebiChart'), {
    type:'bar',
    data:{ labels: data.map(function(r){ return r.Date; }), datasets:[{ data: data.map(function(r){ return parseInt(r.Bebis); }), backgroundColor:'#B24BF399', borderColor:'#B24BF3', borderWidth:1, borderRadius:2 }]},
    options:{ responsive:true, maintainAspectRatio:true, plugins:{ legend:{ display:false }},
