// 11: Guten Morgen
builders[11] = function(){
  var count = parseInt(D.gutenMorgen[0].Value);
  var el = document.getElementById('morgenNum');
  el.classList.add('visible'); animN(el, count);
};

// 12: Search
builders[12] = function(){
  var input = document.getElementById('searchInput');
  document.querySelector('#s12 .chart-wrap').classList.add('visible');
  input.addEventListener('input', doSearch);
  input.addEventListener('keydown', function(e){ e.stopPropagation(); });
  input.addEventListener('keyup', function(e){ e.stopPropagation(); });
};

var searchChart = null;
function doSearch(){
  var q = document.getElementById('searchInput').value.trim().toLowerCase();
  var res = document.getElementById('searchResults');
  if(!q){ res.innerHTML='<p class="subtitle">Start typing to search&hellip;</p>'; if(searchChart){searchChart.destroy();searchChart=null;} return; }
  var total=0, jc=0, lc=0, daily={};
  for(var i=0;i<CHAT.length;i++){
    var r=CHAT[i];
    if(r[2].toLowerCase().indexOf(q)!==-1){
      total++;
      if(r[1]==='Jonas') jc++; else lc++;
      daily[r[0]]=(daily[r[0]]||0)+1;
    }
  }
  res.innerHTML='<div class="big-number visible" style="font-size:clamp(2rem,8vw,5rem)">'+total.toLocaleString()+'</div>'+
    '<p class="subtitle">messages contain "'+q.replace(/</g,'&lt;')+'"</p>'+
    '<div class="stat-row">'+
    '<div class="stat-card visible"><div class="label">Jonas</div><div class="value jonas-color">'+jc.toLocaleString()+'</div></div>'+
    '<div class="stat-card visible"><div class="label">Laura</div><div class="value laura-color">'+lc.toLocaleString()+'</div></div>'+
    '</div>';
  /* build daily chart */
  var dates=D.totalPerDay.map(function(r){return r.Date;});
  var vals=dates.map(function(d){return daily[d]||0;});
  if(searchChart) searchChart.destroy();
  searchChart = new Chart(document.getElementById('searchChart'),{
    type:'bar',
    data:{labels:dates,datasets:[{data:vals,backgroundColor:'rgba(29,185,84,0.45)',borderColor:'#1DB954',borderWidth:1,borderRadius:2}]},
    options:{responsive:true,maintainAspectRatio:true,plugins:{legend:{display:false}},
      scales:{x:{type:'time',time:{unit:'month'},grid:{display:false},ticks:{font:{size:10}}},y:{beginAtZero:true,grid:{color:GC}}},
      animation:{duration:600}
    }
  });
}

init();
</script>
</body>
</html>